INSERT INTO vi_biz_model_base (company_id, code, element, title, content, metric, trend) VALUES
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B1', '客户细分', '两大电网公司，电量最终送往长三角、珠三角和华中', '电卖给国家电网、南方电网，终端在受电省份：三峡丰水期送广东、华东各半，枯水期广东 16%、华东 32%、华中 52%；溪洛渡送浙江、广东，向家坝送上海，乌东德送广东、广西并留存云南，白鹤滩送江苏、浙江并留存四川、云南。', '受电区域是全国电价最高的长三角、珠三角', '外送电与受电省份的本地电源（煤电、核电、新能源）在价格上可比，受电省份电价下行会传导到倒推电价和市场化电价（T3）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B2', '价值主张', '清洁、可调节的大规模电力', '年发电约 3,000 亿千瓦时，可满足 3 亿多人一年的用电。水电没有燃料成本、出力可快速调节，在新能源占比上升的电力系统里兼有电量、调峰与绿色价值；常规水电已纳入绿证核发。', '年发电约 3,000 亿千瓦时', '电力市场化后，调节价值（辅助服务、调峰）有望单独定价；电量价值则随受电省份电价走（V5、T3）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B3', '渠道通路', '特高压外送通道，不需要获客', '电量通过配套的特高压直流外送到华东、广东，属于国家“西电东送”的骨干电源，由电网保障消纳；没有营销与获客成本。', '销售费用率约 0.2%—0.3%', '外送通道容量与电网调度决定送出上限；受电省份对外来电的接纳与价格谈判是唯一的“渠道”风险（V4、V5）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B4', '客户关系', '大宗中长期合同、按月结算，电价由政策机制决定', '与两大电网签大宗中长期合同、按月结算，客户只有两家，但电网保障消纳，不存在“丢客户”。电价按机制定：葛洲坝成本加成；三峡按受电省份落地电价倒推（落地价−输电价−线损）；金沙江四站为倒推电价加市场化电价，白鹤滩过渡期后全部市场化（事实卡“电价机制”）。关系稳定来自管制，不来自公司自身（伪壁垒 M5）。', '客户 2 家（国家电网、南方电网）；按月结算', '市场化电量占比上升后，价格更多随受电省份的年度交易均价走（2026 年广东、江苏、浙江年度长协均下降，T3）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B5', '收入来源', '发电量×电价：境内水电约 88%，来水决定年度波动', '收入＝发电量×上网电价（发电量＝装机×利用小时）。2025 年：境内水电 756.6 亿元（毛利率 65.8%）；其他行业 103.2 亿元（毛利率 31.5%），主要是秘鲁路德斯公司（配售电）、国内配售电与新能源；投资收益 49.59 亿元不在营收里（B8）。单价与利用率：综合电价 0.2807 元/千瓦时，利用小时约 4,280（3071.94 亿千瓦时÷7169.5 万千瓦）。驱动：短期发电量随来水波动（2022 年枯水、2026 年三季度偏枯），六库联调平滑一部分（M3）；长期装机已基本到顶，新增只来自扩机增容（约 437.5 万千瓦）和抽水蓄能（2028 年起才有收入，T6）。', '2025 年：发电量 3071.94 亿千瓦时、综合电价 0.2807 元/千瓦时、营收 862.42 亿元；境内水电占营收约 88%、占毛利约 94%；2023—2025 年发电量 2762.63 / 2959.04 / 3071.94 亿千瓦时', '收入端取决于来水（T2）和电价（T3），度电收入受市场化电价压制；国际与配售电业务毛利率低，受汇率与当地监管影响；气候变化与连续枯水是主要的不确定性；资产注入式的增长已基本结束（M7）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B6', '核心资源', '长江干流六座梯级电站', '六座梯级电站（三峡、白鹤滩、溪洛渡、乌东德、向家坝、葛洲坝）沿长江干流 1,800 多公里排列，水位落差 900 多米，开发权与坝址不可复制（M1）。电站由三峡集团建成后注入公司（2016 年溪洛渡、向家坝，2023 年乌东德、白鹤滩）；同一条河上的六座水库可以联合调度（M3）。', '水电总装机 7179.5 万千瓦，境内六站 7169.5 万千瓦；全球前 12 大水电站占 5 座（价值手册）', '资产注入是历史上最大的增长来源，2016、2023 年两轮之后已基本完成；之后看扩机、抽蓄（M8）与参股企业的投产（T6）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B7', '关键业务', '梯级联合调度、电站运维，转向抽蓄与扩机建设', '电站运行与六库联合调度（多蓄水、少弃水，提高水能利用率）、大坝与机组的检修维护、库区管理；扩机增容与抽水蓄能建设；对外股权投资与国际配售电运营。', '六库联调：2025 年节水增发电量 140.1 亿千瓦时，水能利用提高率 4.68%', '运营上的提升空间有限，未来几年的重点从“运营”转向“建设”（抽蓄、葛洲坝航运扩能），资本开支上升（B9）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B8', '重要合作', '控股股东三峡集团、参股上下游能源企业', '控股股东三峡集团建设电站再注入公司（B6），2026 年增持 44.99 亿元。参股受电区域和长江上游的能源企业（如国投电力、川投能源），投资收益在枯水年平滑利润（事实卡“投资收益”）。', '2025 年投资收益 49.59 亿元（权益法 46.16 亿元），2020 年以来每年约 40—55 亿元', '参股企业的投产与分红决定投资收益的增长（T6）；权益法收益只有一部分以现金分回（B9）。'),
((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B9', '成本结构', '没有燃料，成本约八成固定；现金远多于利润', '成本约八成是固定的：2024 年成本费用中折旧约 38.6%、财务费用约 22.1%、资源税与城建税等规费约 7.2%、材料、薪酬与库区维护基金等约 32%。折旧、利息不随发电量变化，规费随收入变化，所以利润对发电量和电价高度敏感（经营杠杆高），对成本几乎不敏感。所得税：母公司 25%，川云（溪洛渡、向家坝）15%，云川（乌东德、白鹤滩）减半期 7.5%。单位利润：每度电收入约 0.28 元、归母净利约 0.112 元（345.03 亿÷3071.94 亿千瓦时），其中折旧约 0.064 元/千瓦时是非现金成本。现金：折旧不付现，2025 年经营现金流 605.63 亿元，是归母净利的 1.76 倍；资本开支 184.88 亿元（含扩张），分红约 245 亿元（派息率 70.9%），净还债约 95 亿元。权益法收益 46.16 亿元里只有 26.35 亿元以现金分红收回，所以归母利润与可分配现金之间要做桥接（J-CASH）。', '2025 年：毛利率 61.7%、归母净利 345.03 亿元、折旧 195.29 亿元、财务费用 93.71 亿元（−17.60 亿元）；度电收入 0.281 元、度电归母净利 0.112 元；经营现金流÷归母净利 1.76；资本开支÷经营现金流 0.31', '折旧到期与还债降息让成本逐年下降、度电利润上升（T4），卖方测算未来五到十年 EPS 年化约 4%；乌东德、白鹤滩将退出所得税减半期，税率会上升（问题清单 Q11）；2026—2030 年扩张资本开支（抽蓄、葛洲坝航运扩能）会抬高资本开支，现金桥接显示部分年份 FCFE 低于计划股息（J-CB2026、T5）。');
INSERT INTO vi_lnk_biz_model_facts (biz_model_id, fact_id, "createdAt", "updatedAt")
INSERT INTO vi_fact_base (company_id, title, category, statement, value, unit, period, as_of, verify_status, source_id) VALUES ((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), '销售模式：直销 53%、经销 47%，境外 3.6%（2025 年）', '经营', '2025 年年报：直销 208.89 亿元（占营收 53.30%，毛利率 14.55%）、经销 183.03 亿元（46.70%，毛利率 16.77%）；境内 377.78 亿元（96.39%）、境外 14.14 亿元（3.61%，+82.99%）。内销分直发销售和售后代管商品（货物转入代管仓、客户签出库单后确认收入）；与经销商为买断式销售；部分合同有销售返利。2024 年直销 218.82 亿元（毛利率 18.47%）、经销 188.44 亿元（毛利率 13.15%）。', 0.533, '比率', '2025', '2025-12-31', '已核验', (SELECT id FROM vi_source_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') AND title = '太阳纸业 2025 年年度报告'));
INSERT INTO vi_biz_model_base (company_id, code, element, title, content, metric, trend) VALUES
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'B1', '客户细分', '纸箱厂、印刷与出版、粘胶纤维厂，第一大客户是关联方', '包装纸卖给纸箱厂（下游是消费品、电商、家电与出口）；文化纸卖给出版社、印刷厂（教材教辅、出版物、办公用纸）；溶解浆卖给粘胶短纤厂（纺织）；化学浆、化机浆主要卖给集团的白卡纸业务（关联方，B8）。', '前五大客户合计 21.87%，第一大客户（关联方）11.06%（2025 年）', '文化纸需求随出生人口与电子化长期下降（V7）；包装纸需求跟消费与出口（V6）。'),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'B2', '价值主张', '包装纸、文化纸、生活与特种纸、浆：靠成本、质量稳定与交期', '包装纸（牛皮箱板、瓦楞，以高端牛卡为主，约占 75%）；文化纸（双胶、铜版，均为行业前列）；生活纸与特种纸（食品级牛皮纸、衬纸等，颜店、南宁扩产）；浆（溶解浆、化学浆、化机浆，溶解浆是国内两家稳定供应商之一）。卖点是成本、质量稳定与交期，不是品牌溢价。', '双胶纸市占率约 16.5%、铜版纸约 18%（行业第二）、溶解浆产能约 80 万吨', '价值主张从“文化纸龙头”转向“高端包装纸＋特种纸”（T2）。'),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'B3', '渠道通路', '直销与经销约各半，以内销为主', '内销为主，分直发销售和售后代管商品（货物转入代管仓，客户签出库单后确认）；与经销商为买断式销售，部分合同有销售返利。2025 年直销 208.89 亿元（53.3%，毛利率 14.55%）、经销 183.03 亿元（46.7%，毛利率 16.77%）；境外销售 14.14 亿元（3.6%，+83%）。纸是标准品，渠道的作用是覆盖与交付，不是溢价来源。', '直销 53.3%、经销 46.7%；境外 3.6%（2025 年）', '直销与经销的毛利率 2024、2025 年高低互换（18.47%、13.15% → 14.55%、16.77%），看不出渠道本身有议价力；境外增长快但基数小。'),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'B4', '客户关系', '交易型关系：按订单、随行就市，客户换供应商成本低', '纸箱厂、印刷厂按订单和市场价采购，同规格的纸可以互相替代，客户换供应商的成本低；价格随行业涨价函与淡旺季调整（2026 年 4—7 月箱板纸淡季提价约 400 元/吨，事实卡“市场份额”）。维系客户靠质量稳定、交期与部分合同的销售返利；关联方采购是相对稳定的需求（B1）。', '2026 年 4—7 月箱板纸淡季提价约 400 元/吨', '关系不带来定价权，利润差异只能来自成本（B9）；关联交易定价要盯（T4）。'),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'B5', '收入来源', '浆纸销量×吨收入：包装纸升到约三分之一，产能扩张带来销量', '收入＝浆纸销量×综合吨收入。纸是大宗品，价格随行业供需与浆价波动，公司是价格接受者。2025 年吨收入约 4,219 元（391.92 亿元÷929 万吨）。结构：2026 年上半年包装纸 73.6 亿元（35%）、文化纸 54.2 亿元（26%）、生活纸、特种纸及其他 41.5 亿元（20%）、浆 28.4 亿元（14%）；箱板纸收入占比 2023 年 24.8% → 2025 年 29.0% → 2026 年上半年 33.9%。增长：浆纸产能从 2025 年末超过 1,400 万吨增到 2026 年 9 月约 1,600 万吨（含自用浆），南宁技改 2027 年四季度试产，之后增速放缓（T2）。周期：纸价与浆价错配、行业集中投产、文化纸需求长期下降都会压缩价差（敏感性见 B9）。', '2025 年：销量 929 万吨（纸 799、外销浆 130）、营收 391.92 亿元；销量 2019 年 471 → 2025 年 929 万吨；2026 年上半年箱板纸收入 70.76 亿元（+35.54%）、毛利率 18.48%', '吨收入随产品结构转向包装纸而下降（T2）；新产能全部投在包装纸与特种纸，文化纸占比继续下降；碳市场纳入造纸（2027 年首次履约）、新产能审批趋严，可能加速落后产能出清（V12）。'),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'B6', '核心资源', '三大基地、老挝林地、自制浆线与热电联产', '山东（兖州、邹城、颜店）：高端包装纸、文化纸、特种纸；广西（北海、南宁）：近年新增产能的主力；老挝：林地、溶解浆、包装纸。自制浆线（木浆自给率六成以上）、热电联产与老挝自有木片是成本优势的物质基础（M1、M2、M3，成本作用见 B9）。', '老挝基地 2025 年净利约 4.96 亿元，资产约占净资产 37%；老挝林地 2026 年底约 7 万公顷，自有木片比市价低 30—50 美元/吨', '颜店 60 万吨化学浆（2026 年 9 月）、南宁 50 万吨本色浆（2027 年四季度）投产后自给率继续上升；林地达到约 10 万公顷后规划老挝新项目（最早 2027 年下半年，T3）。'),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'B7', '关键业务', '建项目、制浆造纸连续生产、经营林地', '一是项目建设与爬坡：连续多年新建浆纸线，项目执行与组织能力是局部优势（M4）；二是制浆与造纸的连续生产，配套热电联产；三是在老挝经营林地和木片供应。高端箱板纸（木浆系牛卡）的产品能力还在验证（M5）。', '高端箱板占比约 75%（山东 90% 以上、南宁约 60%）', '扩张放缓后，重点要从“建项目”转到“提效率与分钱”（T3）。'),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'B8', '重要合作', '控股股东与关联方、外购浆与能源供应商', '实控人李洪信，控股股东持股约 45%；集团内的白卡纸业务是第一大客户（关联方，B1）。木浆自给之外的部分外购，另有木片、废纸、煤与化工品采购，价格随国际浆价和能源价格波动（事实卡“纸浆期货”）。', '控股股东持股约 45%；纸浆期货 4668 元/吨（2026-10-21）', '关联交易的定价与占比要单独盯（T4）。'),
((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'B9', '成本结构', '木浆占成本 50%—60%，赚吨纸价差；现金几乎全部投进新产能', '利润来自“吨纸价差”：纸价减去木浆（木片、废纸）、能源、化工与物流成本。木浆原料占成本 50%—60%，其次是能源、化工与物流；木浆自给率六成以上，自制浆、热电联产、自有木片三项决定了与同业的成本差（M1、M2、M3）。所得税：山东母公司 25%，北海、南宁享 9% 优惠（分别于 2025、2028 年底到期），老挝免利润税至 2032 年。单位利润：2025 年吨归母净利约 350 元（32.51 亿元÷929 万吨）；新产能吨利：高端箱板毛利率 17%—18%、瓦楞约 10%。敏感性：毛利率每变动 1 个百分点，利润总额约变动 4.3 亿元（按营收约 430 亿元计）、归母净利约 3.6 亿元（约一成）。资本：折旧大，经营现金流长期是净利的 1.5—3 倍；但 2019—2025 年累计经营现金流约 401 亿元、资本开支约 406 亿元，股东自由现金近似为零，约 41 亿元分红实际靠借款支付，带息负债从约 125 亿元升到约 200 亿元。', '2025 年：毛利率 15.6%、EBITDA 率约 17.4%、归母净利 32.51 亿元、吨归母净利约 350 元；毛利率 2017 年 26.0% → 2022 年 15.2% → 2025 年 15.6%；经营现金流 49.56 亿元、资本开支 79.29 亿元、净负债 177.7 亿元（净负债÷EBITDA 约 2.6 倍）', '吨成本随自制浆比例上升而下降（T1）；吨利取决于纸价与浆价的价差；税收优惠陆续到期（伪壁垒 M7）；价值取决于扩张什么时候停、停了之后钱给谁（T3、T4）。');
INSERT INTO vi_lnk_biz_model_facts (biz_model_id, fact_id, "createdAt", "updatedAt")
INSERT INTO vi_biz_model_base (company_id, code, element, title, content, metric, trend) VALUES
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B1', '客户细分', '政府与城投占四成以上，住宅降到两成以内，工业与能源业主在增加', '施工业务的业主：地方政府、城投与国企（政府背景业主占房建基建项目 40% 以上）；开发商（住宅占房建订单 20% 以内）；工业、能源、数据中心等产业业主（工业厂房占房建新签 33%、能源工程占基建新签 40%）；海外业主（订单不足 5%）。地产业务的客户是购房者，中海聚焦一二线核心城市。', '政府背景业主 >40%；住宅 <20%；工业厂房占房建 33%；海外 <5%', '风险房企应收是减值源头（T8）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B2', '价值主张', '房建、基建、勘察设计的总承包，加一块地产开发', '房屋建筑（住宅、公建、工业厂房、数据中心、超高层）、基础设施（市政、能源工程、交通、水务）、勘察设计；地产开发与投资（中海地产、中建地产）。卖点是别人干不了的大项目（超高层、复杂公建、大型工业厂房）、按期交付，以及能带着资金进场（M1、M2）；公司自称“规划设计、投资开发、基础设施建设、房屋建筑工程”四位一体。', '三大业务毛利率（2025）：房建 8.4%、基建 9.9%、地产 14.4%', '订单从住宅转向工业厂房、能源、数据中心（B1、B5）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B3', '渠道通路', '招投标为主，过去靠投资（PPP）带动施工，现在靠选项目', '工程项目主要靠公开招投标，大项目看资质、业绩和融资能力（M1、M2）；2023 年 11 月前用 PPP 等投资带动施工总包，之后不再新增 PPP，转向城市更新、投建营一体化与海外；“两优两重”选项目（M4）。', '2026H1 新接项目毛利率 +0.2pt；建筑市场占有率 +2.2pt（管理层）', '投资带动施工的模式在收缩（伪壁垒 M7），订单质量取决于选项目的纪律（T1、T3）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B4', '客户关系', '项目制：一次招投标、一份合同，按节点收款', '与业主是项目制关系：按合同施工、按进度确认收入、按节点付款、质保金后付（资金占用见 B9）。与地方政府、城投的长期关系能带来项目信息与准入，但不带来定价权，也不保证回款（伪壁垒 M6）。地产业务面对购房者，靠品牌、产品与交付（M3）。', '政府背景业主占四成以上，化债力度较去年减弱（管理层）', '业主的付款能力决定现金回收（T4）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B5', '收入来源', '新签合同×收入转化率：房建约六成，订单变收入在变慢', '收入＝新签合同总额×收入转化率（2025 年 45,458 亿元×0.458），施工按进度确认收入。2025 年收入：房建 12,342 亿元（59%）、基建 5,432 亿元（26%）、地产 2,844 亿元（14%）、勘察设计约 1%；境外 1,417 亿元（约 7%）。地产收入只占约 15%，却贡献约 34% 的分部利润总额（2026 年上半年，事实卡）。周期：全国建筑业新签合同额连续三年下降、总产值 2025 年近十年首次下降；公司新签 2023—2025 年稳定在 4.3—4.5 万亿元（份额上升，T1），但订单变成收入的速度在变慢（收入转化率 0.54 → 0.46，原因与前景见 T2）。增量：工业厂房、能源工程、数据中心、城市更新（含中国建筑国际旗下中建海龙的模块化建筑 MiC）、海外（订单高增、毛利率低）。地产随销售周期，合约销售连续三年下降（事实卡）。', '2025 年营收 20,821 亿元；新签 +1.0%、收入 −4.8%；2026 年 1—9 月新签 −0.1%、房建新开工 −18.1%；地产收入占约 15%、利润总额占约 34%（2026H1）', '收入转化率在降，收入能否在 2027 年见底，是经营模型最大的问题（T2）；房建收入 2026 年上半年 −18%；地产利润占比高，意味着中国建筑的估值有一部分是地产股（M3、T8）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B6', '核心资源', '央企信用与资质、全国与海外施工网络、两个港股平台', '央企信用与低成本资金（M1）；资质、业绩与超大复杂项目的总承包能力（M2）；施工网络覆盖全国与海外近百个国家和地区；持股中国海外发展（中海地产）56.1%、中国建筑国际（含中建海龙）61.8%；中建财务公司。', '评级 A/A2/A；平均债务成本约 1.96%；中海权益销售 2025 年行业第一', '信用优势让它在下行期拿份额，也让它更愿意垫资（T1、T4）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B7', '关键业务', '拿项目、组织分包、垫资和承担风险', '大部分工作量交给分包与劳务（B8、B9），公司的价值在拿项目、组织管理、垫资和承担风险：投标与选项目（“两优两重”，M4）、总包管理与成本管控、设计施工一体化；地产业务的拿地、开发与销售由中海地产等平台运营（M3）。', '分包＋原材料＋劳务约占成本与费用 73%', '能不能把毛利守住，看选项目与成本管控是否真的有效（M4 待验证）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B8', '重要合作', '控股股东中建集团、分包与供应商、子公司的少数股东', '控股股东中建集团持股 57.73%。分包商、材料供应商与劳务队伍承担大部分施工量，回款慢的压力一部分传给他们（应付票据及账款 2023 年 7,007 亿元 → 2025 年 10,091 亿元，V1）。中海地产、中国建筑国际等子公司有外部股东，少数股东分走约 27% 的净利润（T6）。', '控股股东持股 57.73%；少数股东分走约 27% 的净利润', '分包与供应商的承受力是垫资模式的边界（V1）。'),
((SELECT id FROM vi_company_base WHERE code = '601668.SH'), 'B9', '成本结构', '分包、材料、劳务占七成以上，归母只剩收入的约 2%；利润沉淀在应收里', '2025 年成本与费用（19,630 亿元）里分包约 37%、原材料约 24%、劳务约 12%，其余是地产结转、其他施工成本与职工薪酬（事实卡）。施工毛利 8%—11%，扣掉费用后核心利润率约 6.2%（不含减值）。每 100 元收入：营业成本 90.1 元、税金 0.4 元、销售管理研发费用 4.2 元、财务费用 0.85 元、减值 1.24 元（约收入的 1.2%），利润总额 3.4 元；所得税 0.8 元、少数股东 0.7 元，归母净利 1.9 元（2019 年 3.0 元）；即归母净利≈利润总额×56%（税 24%、少数股东 26%）。资本：先垫资后收款——业主按节点付款、质保金后付，回款慢于确认；每 1 元收入对应的应收账款＋合同资产从 2019 年 0.21 元、2023 年 0.26 元升到 2025 年 0.48 元。经营现金流长期只有利润的一到五成（事实卡）；PPP 存量权益投资 5,951 亿元。购建长期资产约 260 亿元/年，真正的资本需求是营运资本。', '2025 年：毛利率 9.9%、核心利润率 6.2%、归母净利 390.7 亿元、归母净利率 1.9%（2019 年 3.0%）；经营现金流 205.4 亿元；应收＋合同资产 10,045 亿元（÷收入 0.48，2019 年 0.21）', '收入大、利润薄，利润对利润率极其敏感（J-M）；利润率变薄主要来自减值与少数股东，减值在升（T8）；收入下降时费用刚性（2026H1 期间费用率 +0.44pt，T3）；资本占用翻倍来自回款变慢，化债回款能否让营运资本占用逐年下降（T4、J-WC）。');
INSERT INTO vi_lnk_biz_model_facts (biz_model_id, fact_id, "createdAt", "updatedAt")
INSERT INTO vi_biz_model_base (company_id, code, element, title, content, metric, trend) VALUES
((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'B1', '客户细分', '三层用户＋广告主＋演出观众', '重度与粉丝用户（超级会员 2,000 万以上，集中在 QQ 音乐）、大众付费用户（约 1.27 亿）、轻度与下沉免费用户（酷狗、酷我、轻量 App），另有广告主和演唱会观众。', '月活 5.28 亿、付费用户 1.274 亿，付费率约 24%（2025 年四季度）', '轻度层正被汽水音乐、番茄音乐的免费模式分流，核心付费层是否受影响见 T3。'),
((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'B2', '价值主张', '最全的正版曲库、多端体验和粉丝权益', 'QQ 音乐（综合、偏一二线）、酷狗与酷我（下沉、价格敏感）、全民 K 歌、波点等轻量 App，2026 年起加上喜马拉雅长音频。核心卖点：曲库约 2.6 亿首、覆盖 95% 以上华语热门（含周杰伦等头部版权）；无损与杜比音质、车机与智能设备多端；超级会员的演唱会优先购票、Bubble、周边与长音频权益。', '曲库约 2.6 亿首（对手对比见 M2）；QQ 音乐会员 20—40 元/月，行业最高', '对只听抖音热歌的轻度用户，“曲库全”的价值在下降；价值主张正从“歌全”转向“权益全”。'),
((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'B3', '渠道通路', '腾讯生态带来的低获客成本', '微信、QQ 的社交入口与关系链，手机和车机预装，应用商店分发；2026 年接管微信视频号音乐垂类运营，接入元宝、小微 AI 助手。', '销售费用率 2025 年 2.9%（网易云 2026 年上半年 7.5%）；2026 年一季度销售费用同比 +36%', '音乐“发现”越来越多发生在抖音（V5），公司开始向字节等渠道买量，获客成本在上升；腾讯生态能否对等抖音见 T2。'),
((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'B4', '客户关系', '订阅制、高续费：歌单与会员权益留住用户', '会员按月或按年订阅。音乐是高频、重复收听的需求（用户约 90% 的播放是重复收听，行业交流口径），不需要多平台订阅；歌单、收藏与会员权益形成转换成本（是否构成壁垒见 M3）。超级会员把粉丝权益（B2）变成更深的关系（M5）。', '续费率 80% 以上（行业交流口径）', '管理层称竞争冲击轻度用户，超级会员稳定；免费模式对轻度用户的分流见 T3。'),
((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'B5', '收入来源', '会员约 54%，营销及消费类升到 31%，社交娱乐降到 15%', '收入＝付费用户×ARPPU×12（会员服务）＋广告、演唱会、艺人周边、长音频（营销及消费类）＋直播打赏（社交娱乐）。结构：2025 年会员 53.7%、营销及消费类 27.6%、社交娱乐 18.8%；2026 年二季度会员 53.6%、营销及消费类 31.5%、社交娱乐 14.9%。单价：ARPPU 2022 年 8.9 元 → 2025 年 11.9 元，2026 年二季度中金估算约 12.5 元（可能含喜马拉雅会员）；网易云约 6.4 元，Spotify 约 4.9 欧元（但付给版权方的比例更高）。', '2025 年：会员 176.6、营销及消费类 90.7、社交娱乐 61.8 亿元，ARPPU 11.9 元；营销及消费类 2025 年 +39%、2026 年二季度 +16%；社交娱乐二季度 −16%', '增长引擎从“付费用户×ARPPU”转向“超级会员＋IP 衍生”（能否接替订阅见 T4）：高毛利的会员内生增长约持平，低毛利的演出与经纪在补位；社交娱乐随直播监管持续收缩（V11）。汽水 8 元/月、看广告免费，压住了提价空间；ARPPU 提升越来越依赖超级会员占比，而不是普通会员提价。'),
((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'B6', '核心资源', '长期版权授权、自制音乐、对唱片公司的持股', '与环球、索尼、华纳及杰威尔、华研等长期授权（期限 1—3 年，最低保底＋分成），与音著协有框架协议，构成头部华语曲库（B2、M2）。自制音乐播放份额约 20%—30%，已超过三大唱片在平台的份额（约 20%，中金估算）。持有 UMG 约 2%、WMG 0.8%、SME 9.7%、Spotify 2.5%（摩根士丹利口径）。', '对外股权约 191 亿元（2026 年 6 月）', '授权都是非独家的，竞争对手也能拿到大部分曲库；对唱片公司的持股带来关系，但不带来排他权。'),
((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'B7', '关键业务', '版权采购、产品与推荐运营、IP 与演出、长音频', '规模化采购与续约版权（上游议价权是真实壁垒，M1）；QQ 音乐、酷狗、酷我的产品与推荐运营；自制音乐与艺人经纪；演唱会、周边等 IP 与粉丝经济运营（M5）；2026 年起运营喜马拉雅长音频。', '经营费用率从 18% 降到 15%', 'AI 音乐日上传量约 40%、播放只占 1%—3%，内容供给方式在变，平台目前不给 AI 歌曲结算版税（事实卡）。'),
((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'B8', '重要合作', '控股股东腾讯、三大唱片与独立版权方', '腾讯控股是控股股东，提供社交入口与关系链（渠道见 B3）。三大唱片（环球、索尼、华纳）及杰威尔、华研等是最主要的版权方，公司同时持有三大唱片的股权（B6）；国内版权方分散，平台议价力强（M1）。', '国内前五大唱片公司约 29%；平台付给版权方约 45%—55%', '授权期限 1—3 年，续约时重新议价（M1）；腾讯生态资源的分配决定低获客成本能否持续（T2）。'),
((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'B9', '成本结构', '营业成本约 56%、以版权分成为主；会员预付、版权后付，不占用资金', '利润＝收入−版权分成与内容成本−主播分成−演出与周边成本−获客与管理费用。营业成本包括版权分成与内容成本、主播分成、演出和周边成本、带宽与渠道费；经营费用约占收入 15%（管理及研发约 12%、销售约 3%）。国内平台付给版权方的比例约为相关收入的 45%—55%，海外约 60%—70%。毛利率高出同业 7—12 个百分点（网易云 37.2%、Spotify 30% 出头），续费率高也压低了获客成本（B4）。资本：负营运资本约 80 亿元（应付账款、预收会员费、其他应付减应收与预付）；资本开支每年约 12 亿元。2025 年末，经营性投入资本（归母权益＋少数股东＋带息负债−现金存款−对外投资）约 205 亿元，几乎等于商誉；剔除商誉后为负。', '2025 年营业成本 183.7 亿元（收入的 55.8%）、毛利率 44.2%、核心经营利润率 29.4%；经营现金流约 100 亿元/年，约等于经调整净利；按含商誉的投入资本算，税后经营回报约 39%', '2021 年取消独家版权后，版权成本率下降（毛利率与壁垒的关系见 M1）；演出占比上升会把毛利率往回拉，单位收入带来的利润在下降；收入停止增长时，负营运资本不再释放现金；钱主要花在并购（喜马拉雅约 80 亿元现金）和回购上（利润的现金含量见 T6，股东回报见 T5）。');
INSERT INTO vi_lnk_biz_model_facts (biz_model_id, fact_id, "createdAt", "updatedAt")
INSERT INTO vi_biz_model_base (company_id, code, element, title, content, metric, trend) VALUES
((SELECT id FROM vi_company_base WHERE code = '01810.HK'), 'B1', '客户细分', '全球 7.67 亿月活，境外收入约 36%', '中国大陆月活 1.98 亿，境外占多数（东南亚、拉美、中东份额第二，欧洲、非洲第三）；汽车客户以一二线城市年轻用户和家庭用户为主。', '2026 年上半年境外收入占 37.9%', '境外用户 ARPU 低、对价格敏感，存储涨价打击最大。'),
((SELECT id FROM vi_company_base WHERE code = '01810.HK'), 'B2', '价值主张', '“感动人心、价格厚道”：同配置更便宜，并逐步高端化', '2018 年承诺硬件综合净利率不超过 5%；手机覆盖 Redmi（入门）到 Xiaomi 数字旗舰与 Ultra（4,000—10,000 元），与徕卡合作影像；IoT 覆盖可穿戴、平板、电视、大家电；汽车 SU7、YU7、澎程覆盖 20—35 万元。', 'ASP 1,351 元（2026Q2，历史新高）；中国大陆 3,000 元以上机型占比 32.1%', '高端化提高了单价，但在 3,000 元以上市场华为、苹果份额也在上升；低端是被存储涨价伤得最重的价位段。'),
((SELECT id FROM vi_company_base WHERE code = '01810.HK'), 'B3', '渠道通路', '线上起家，线下自建新零售，汽车共用渠道', '小米之家在中国大陆约 1.6—1.8 万家（500 平米以上大店 270 多家），境外新零售门店 640 多家，计划年底超过 1,000 家；汽车门店 477 家（2025 年末）。电商（小米商城、京东、天猫）与海外运营商渠道。', '2025 年销售费用 332.1 亿元（收入的 7.3%）', '门店扩张推高费用；国补退坡后门店客流与家电销售下降。'),
((SELECT id FROM vi_company_base WHERE code = '01810.HK'), 'B4', '客户关系', '设备即账户：硬件卖出后，互联网服务持续变现', '手机、IoT 与汽车用户使用同一套小米账号与澎湃 OS，设备在用户手里，就持续带来互联网服务收入（B5）——这是“硬件按接近成本定价”能成立的前提（M1）。品牌与创始人号召力维系用户（M4）；汽车吸引了大量非小米手机用户。', '新一代 SU7 锁单用户中苹果手机用户近 60%（初代约 50%）', '汽车用户与手机生态的重合度不高，“人车家全生态”协同是伪壁垒（M6）。'),
((SELECT id FROM vi_company_base WHERE code = '01810.HK'), 'B5', '收入来源', '硬件按接近成本定价获客、互联网变现：手机四成、IoT 近三成、汽车两成多', '手机、IoT 收入＝出货×ASP，汽车收入＝交付×ASP，互联网收入＝月活×每用户变现。2025 年收入 4,572.9 亿元：手机 1,864.4（40.8%）、IoT 与生活消费产品 1,232.0（26.9%）、互联网服务 374.4（8.2%）、其他 41.4、汽车及 AI 1,060.7（23.2%）。', '2025 年收入 4,572.9 亿元；互联网收入占 8%，贡献生态毛利约 38%', '2026 年上半年汽车占比升到 21.5%，手机与 IoT 收入同比下降。'),
((SELECT id FROM vi_company_base WHERE code = '01810.HK'), 'B6', '核心资源', '用户与设备基础、自研 OS 与芯片、品牌、生态链投资', '全球 7 亿多月活的设备与用户基础（B1）；自研：澎湃 OS、玄戒芯片（出货超百万）、MiMo 大模型（能否成为壁垒待验证，M8）；品牌与创始人号召力（M4）；汽车工厂；生态链投资约 410 家公司、账面 920 亿元。', '对外投资 720.7 亿元（不含理财）', '管理层：未来三年 AI 投入超 600 亿元，2026 年 160 亿元。'),
((SELECT id FROM vi_company_base WHERE code = '01810.HK'), 'B7', '关键业务', '产品定义、OS 与互联网运营、供应链管理、新零售；手机外包、汽车自造', '产品定义与设计（手机、IoT、汽车）、操作系统与互联网服务运营、供应链管理与成本控制（M2）、新零售渠道运营（M3）；手机外包制造，汽车自建工厂、自主量产（M5）；AI 与芯片研发。', '2026—2030 年累计研发预计超 2,000 亿元', '汽车量产与供应链组织能力还在验证（M5）。'),
((SELECT id FROM vi_company_base WHERE code = '01810.HK'), 'B8', '重要合作', '核心器件供应商、徕卡与谷歌、生态链公司', '供应商：高通、联发科（SoC），三星、海力士、美光、长鑫（存储），京东方等（屏幕），宁德时代（动力电池，SU7/YU7 曾占约八成）；徕卡（影像）；谷歌（境外安卓与服务）；电商平台与海外运营商（渠道见 B3）；生态链被投企业（B6）。', '宁德时代曾占 SU7/YU7 动力电池约八成', '关键器件依赖少数供应商；生态链公司的利益与小米并不总是一致。'),
((SELECT id FROM vi_company_base WHERE code = '01810.HK'), 'B9', '成本结构', '物料成本为主、费用率约 16%；生态利润几乎全靠互联网毛利；负营运资本', '生态利润＝硬件毛利（手机＋IoT）＋互联网毛利−研发、销售、行政费用。2025 年：手机毛利 202.7＋IoT 284.2＋互联网 286.4−其他 12.9＝760.4 亿元，费用 482.0 亿元，经营利润 278.4 亿元，几乎等于互联网毛利。汽车单独算：利润＝毛利−汽车研发与渠道费用；AI 目前只有成本。成本：2025 年营业成本 3,554.8 亿元（收入的 77.7%）；研发 331.3（7.2%）、销售 332.1（7.3%）、行政 66.5 亿元（1.5%）；存储、SoC、屏幕是物料大头，低端手机存储占物料成本 60% 以上（2025 年三季度约 30%）。单位经济（每部手机毛利约 120 元，每辆车毛利约 4—6 万元）：手机 2025 年 ASP 1,128.7 元×毛利率 10.9%≈123 元（2026 年二季度 1,351 元×8.5%≈115 元）；互联网 374.4 亿元÷7.54 亿月活≈50 元/年，毛利率 76%；汽车 2025 年 ASP 25.1 万元×分部毛利率 24.3%≈6.1 万元，2026 年二季度 22.9 万元×19.2%≈4.4 万元，分部每辆车经营亏损约 2.5 万元（含 AI）。资本：贸易应付 1,183.3 亿元，存货 848.8、应收 197.7 亿元（2026-06-30）：先收款后付款，现金里有一部分是供应商资金。手机外包制造，资本开支低；汽车自建工厂、AI 买算力，2026 年上半年资本开支 68.9 亿元，汽车及 AI 占 56%。不派股息，回购为主。', '2025 年生态经营利润率 7.9%、互联网毛利 286.4 亿元；研发 331 亿元，股权激励每年约 45—50 亿元；每辆车经营损益：2025 年＋0.2 万元，2026 年二季度 −2.5 万元（含 AI）；现金储备 2,193 亿元；2025 年经营现金流 341.4 亿元', '存储涨价让硬件毛利塌陷（T2），成本受全球存储周期左右、小米议价力有限；互联网毛利是利润底座（T1）；AI 每年 160—230 亿元的投入正在吃掉生态利润的一半以上（T4），研发与 AI 投入是半固定成本；汽车的单车经济取决于 ASP 和 AI 摊销，手机靠“量”，量在下滑；出货下滑时负营运资本回流（2026 年一季度经营现金流 −17.9 亿元）。');
INSERT INTO vi_lnk_biz_model_facts (biz_model_id, fact_id, "createdAt", "updatedAt")
