JOIN vi_biz_model_base x ON x.company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND x.code = v.k1 JOIN vi_fact_base y ON y.company_id = (SELECT id FROM vi_company_base WHERE code = '600900.SH') AND y.title = v.k2;

UPDATE vi_thesis_base SET bull_case = '1）六站装机 7169.5 万千瓦、利用小时约 4,300，2023—2025 年发电量约 2,760—3,070 亿千瓦时（B5）。2）六库联调平滑来水（M3）：2025 年节水增发 140.1 亿千瓦时；2026 年上半年三峡偏丰、乌东德偏枯，合计仍 +4.81%。3）枯水是周期而非趋势：2022 年四站发电 −10.9%，2023 年起恢复；厄尔尼诺年份南方降水偏多。4）三季度三峡把部分来水转为库容，四季度枯水期释放：前三季度已完成年度计划（约 3,060 亿千瓦时）的 73.55%。' WHERE id = 378;

