UPDATE vi_thesis_base SET bull_case = '1）销售费用率约 3%，网易云 7.5%：腾讯生态长期让获客几乎免费（B3、M4）。2）腾讯音乐已接管微信视频号音乐垂类运营，打通“视频号发现→QQ 音乐全曲收听”；QQ 音乐接入元宝、小微。3）微信支付为轻量 App 引流，视频号仍在增长。' WHERE id = 332;

UPDATE vi_thesis_base SET bull_case = '1）2026 年二季度单季回购 4 亿美元（约占股本 2.8%），9 月发行 10 亿美元票据，用途写明含回购；管理层称准备新一轮回购、探讨不同的股东回报方式。2）2023 年起每年分红，每股 0.07 → 0.09 → 0.12 美元；回购 2021—2024 年每年 12—35 亿元。3）净现金约 273 亿元、经营现金流约 100 亿元/年、资本开支只要约 12 亿元：钱足够，再投资需求很低（B9、T6）。4）扣除净现金和对外投资后，经营业务只值约 4 倍利润，此时回购的每股增值效果大。5）腾讯控股是控股股东（列为非全资附属公司），在视频号、元宝、广告与支付上提供生态协同，也从回购中被动增持，利益大体一致。' WHERE id = 335;

UPDATE vi_thesis_base SET bull_case = '轻资产、负营运资本（机制见 B9）：经营现金流 2024—2025 年约 102 亿元，约等于经调整净利；资本开支每年 10—12 亿元。这让股息＋回购可以接近 100% 的利润（T5）。' WHERE id = 336;

UPDATE vi_moat_base SET financial_link = '毛利率高出同业 7—12 个百分点（B9）；经营性投入资本约等于商誉，按含商誉的投入资本算税后经营回报约 39%（B9）。' WHERE id = 163;

DELETE FROM vi_biz_model_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '01810.HK');


