UPDATE vi_thesis_base SET bull_case = '1）硬件公司靠负营运资本（先收款、后付款）运转（B9），经营现金流通常高于利润：2023—2025 年经营现金流÷归母净利 2.36、1.66、0.82。2）归母净利含大额投资公允价值收益（2025 年 133 亿元），比率被压低，需要看剔除后的口径。', bear_case = '2026 年上半年经营现金流只有 20.5 亿元（备货、预付增加）；出货下滑时负营运资本会回流（B9）。' WHERE id = 361;

UPDATE vi_thesis_base SET bull_case = '1）硬件按接近成本卖出（综合毛利率约 20%，扣除研发、销售、行政后接近盈亏平衡），利润来自互联网：2025 年互联网服务毛利 286.4 亿元，几乎等于生态经营利润 278.4 亿元（B9）。2）月活连续十年增长、互联网毛利率稳定在 75%—78%（M1）：硬件卖得再便宜，只要设备在用户手里，每个用户每年就有约 50 元的高毛利收入（B9）。3）11.6 亿台 IoT 设备和米家、小爱的高活跃让用户难以离开。' WHERE id = 356;


UPDATE vi_source_base SET summary = regexp_replace(summary, '^商业模式 (9|10) 个要素、', '商业模式画布 9 项、') WHERE summary ~ '^商业模式 (9|10) 个要素、';

COMMIT;
